impl Ollama {
    /// Embed `inputs` in one `/api/embed` call, one vector per input in order. With
    /// `cpu_only` the request carries `num_gpu: 0` so the model never loads on a GPU.
    /// A model the server does not have is reported with the pull line.
    pub fn embed(&self, model: &str, inputs: &[String], cpu_only: bool) -> Result<Vec<Vec<f32>>> {
        let what = "embed";
        let mut body = json!({ "model": model, "input": inputs });
        if cpu_only {
            body["options"] = json!({ "num_gpu": 0 });
        }
        let v = self.post("/api/embed", &body, what).map_err(|e| match &e {
            Error::Ollama(m) if m.contains("http 404") => Error::Refused(format!(
                "the embedding model {model} is not installed on {}; run `ollama pull {model}` against that host",
                self.base
            )),
            _ => e,
        })?;
        let rows = v["embeddings"]
            .as_array()
            .ok_or_else(|| Error::Ollama(format!("{what}: the reply carried no embeddings")))?;
        let out: Vec<Vec<f32>> = rows
            .iter()
            .map(|r| {
                r.as_array()
                    .map(|a| a.iter().map(|n| n.as_f64().unwrap_or(0.0) as f32).collect())
                    .unwrap_or_default()
            })
            .collect();
        let dim = out.first().map_or(0, Vec::len);
        if out.len() != inputs.len() || dim == 0 || out.iter().any(|r| r.len() != dim) {
            return Err(Error::Ollama(format!(
                "{what}: expected {} vectors of one size, got {}",
                inputs.len(),
                out.len()
            )));
        }
        Ok(out)
    }

fn post_pod(
    &self,
    body: &serde_json::Value,
    name: &str,
    deadline: Option<Instant>,
) -> Result<Pod> {
    let mut retries = 0u32;
    loop {
        let started = Instant::now();
        let resp = self
            .agent
            .post(self.url("/pods"))
            .header("Authorization", self.auth())
            .send_json(body)
            .map_err(|e| Error::http("create pod", e))?;
        let status = resp.status().as_u16();
        let delay = retry_after(resp.headers());
        trace::api("create pod", status, started);
        if status != 429 {
            return read_json(resp, &format!("create pod {name}"));
        }
        let err = match read_json::<Pod>(resp, &format!("create pod {name}")) {
            Ok(pod) => return Ok(pod),
            Err(e) => e,
        };
        if !retry_fits(deadline, delay) {
            trace::warn(&format!(
                "runpod: create {name} was rate limited; Retry-After of {}s does not fit before the plan deadline, so this GPU type is not retried and the next type is not tried",
                delay.as_secs()
            ));
            return Err(err);
        }
        if retries >= CREATE_429_RETRIES {
            return Err(err);
        }
        retries += 1;
        trace::warn(&format!(
            "runpod: create {name} was rate limited; retry {retries} of {CREATE_429_RETRIES} after {}s",
            delay.as_secs()
        ));
        std::thread::sleep(delay);
    }
}

/// The reason recorded when the quote rule turns a verdict into `cannot_tell`.
pub const QUOTE_NOT_FOUND: &str = "quote_not_found";

/// Apply the quote rule. `supported` needs a non-empty quote found in the evidence;
/// `unsupported` may leave the quote empty, but a quote that is given must be found;
/// either failing becomes `cannot_tell` with the reason `quote_not_found`. With no
/// evidence at all (a knowledge check) there is nothing to find a quote in, so the
/// model's verdict stands.
pub fn apply_quote_rule(
    reply: &RawReply,
    evidence: &[Passage],
) -> (VerdictKind, Option<&'static str>) {
    if evidence.is_empty() {
        return (reply.verdict, None);
    }
    let quote_ok = quote_found(&reply.evidence_quote, evidence);
    let given = !normalise(&reply.evidence_quote).is_empty();
    match reply.verdict {
        VerdictKind::Supported if !quote_ok => (VerdictKind::CannotTell, Some(QUOTE_NOT_FOUND)),
        VerdictKind::Unsupported if given && !quote_ok => {
            (VerdictKind::CannotTell, Some(QUOTE_NOT_FOUND))
        }
        v => (v, None),
    }
}

/// Per check type metrics for `outcomes` against `gold`, in a stable order (grounded,
/// reasoning, knowledge). Gold claims without a label are not scored; a check type with
/// no labelled claim has no row. An outcome for a claim not in the gold set is ignored.
pub fn metrics(gold: &[Claim], outcomes: &[Outcome]) -> Vec<CheckMetrics> {
    let said: HashMap<&str, VerdictKind> = outcomes
        .iter()
        .map(|o| (o.claim_id.as_str(), o.verdict))
        .collect();
    [
        CheckType::Grounded,
        CheckType::Reasoning,
        CheckType::Knowledge,
    ]
    .into_iter()
    .filter_map(|ct| {
        let rows: Vec<&Claim> = gold
            .iter()
            .filter(|c| c.check_type == ct && c.label.is_some())
            .collect();
        (!rows.is_empty()).then(|| row(ct, &rows, &said))
    })
    .collect()
}

