    for pid in pair_ids:
        va, vb = verdicts[a].get(pid, not_asked), verdicts[b].get(pid, not_asked)
        ka, kb = keeps(va), keeps(vb)
        for j, v in ((a, va), (b, vb)):
            o = v["outcome"]
            counts[j][o] = counts[j].get(o, 0) + 1
        key = "both_keep" if ka and kb else f"only_{a}" if ka else f"only_{b}" if kb else "neither"
        table[key] += 1
        if ka and kb:
            kept.append(pid)
    kept_set = set(kept)
    old_kept = set(pair_ids) - old_dropped
    return {
        "pairs": len(pair_ids),
        "kept": len(kept),
        "kept_ids": kept,
        "dropped_ids": [p for p in pair_ids if p not in kept_set],
        "judges_disagree": table[f"only_{a}"] + table[f"only_{b}"],
        "agreement": table,
        "outcomes": counts,
        "against_first_check": {
            "kept_by_both_checks": len(kept_set & old_kept),
            "kept_now_dropped_before": len(kept_set - old_kept),
            "dropped_now_kept_before": len(old_kept - kept_set),
            "dropped_by_both": len(set(pair_ids) - kept_set - old_kept),
        },
    }

def choose_pair(
    errors: list[dict], rewrites: list[dict], caliper: float = CALIPER_NATS, ratio: float = SIZE_RATIO
):
    """One kept error and one kept rewrite within `caliper` nats of tail delta and within `ratio`
    of edit size (characters, larger / smaller), preferring the least surprising error (highest
    tail), then the most surprising rewrite (lowest tail). None if no pair fits."""
    for e in sorted(errors, key=lambda c: -c["tail"]):
        for r in sorted(rewrites, key=lambda c: c["tail"]):
            big, small = max(e["edit_chars"], r["edit_chars"]), min(e["edit_chars"], r["edit_chars"])
            if abs(e["tail"] - r["tail"]) <= caliper and small > 0 and big / small <= ratio:
                return e, r
    return None

/// Where a job pod's bootstrap writes the Hugging Face token (root-only), when the
/// profile names a secret. An ssh session does not inherit the container's
/// environment, so `exec` and `run` reach the token through `HF_TOKEN_PATH`.
pub const HF_TOKEN_FILE: &str = "/root/.offrig-hf-token";

/// The variables every job command runs with. `HF_TOKEN_PATH` is always set: with no
/// token configured the file does not exist and Hugging Face downloads anonymously.
pub fn job_env() -> BTreeMap<String, String> {
    let mut env = BTreeMap::new();
    env.insert("HF_HOME".into(), HF_DIR.into());
    env.insert("HF_TOKEN_PATH".into(), HF_TOKEN_FILE.into());
    env.insert("OFFRIG_JOB_DIR".into(), JOB_DIR.into());
    env
}

