/// A dollar amount: digits with an optional `$` and decimal point, never negative.
pub fn parse_usd(text: &str) -> Option<f64> {
    let t = text.trim().trim_start_matches('$').trim();
    let v: f64 = t.parse().ok()?;
    (v.is_finite() && v >= 0.0).then_some(v)
}

