/// rule. `knowledge` is reported but is not part of it.
pub fn passes_default(rows: &[CheckMetrics]) -> bool {
    [CheckType::Grounded, CheckType::Reasoning]
        .into_iter()
        .all(|ct| {
            rows.iter()
                .any(|r| r.check_type == ct && r.passes_default_rule)
        })
