/// Per check type metrics for `outcomes` against `gold`, in a stable order (grounded,
/// reasoning, knowledge). Gold claims without a label are not scored; a check type with
/// no labelled claim has no row. An outcome for a claim not in the gold set is ignored.
pub fn metrics(gold: &[Claim], outcomes: &[Outcome]) -> Vec<CheckMetrics> {
    let said: HashMap<&str, VerdictKind> = outcomes
        .iter()
        .map(|o| (o.claim_id.as_str(), o.verdict))
        .collect();
    [
        CheckType::Grounded,
        CheckType::Reasoning,
        CheckType::Knowledge,
    ]
    .into_iter()
    .filter_map(|ct| {
        let rows: Vec<&Claim> = gold
            .iter()
            .filter(|c| c.check_type == ct && c.label.is_some())
            .collect();
        (!rows.is_empty()).then(|| row(ct, &rows, &said))
    })
    .collect()
}

/// Per check type metrics for `outcomes` against `gold`, in a stable order (grounded,
/// reasoning, knowledge). Gold claims without a label are not scored; a check type with
/// no labelled claim has no row. An outcome for a claim not in the gold set is ignored.
pub fn metrics(gold: &[Claim], outcomes: &[Outcome]) -> Vec<CheckMetrics> {
    let said: HashMap<&str, VerdictKind> = outcomes
        .iter()
        .map(|o| (o.claim_id.as_str(), o.verdict))
        .collect();
    [
        CheckType::Grounded,
        CheckType::Reasoning,
        CheckType::Knowledge,
    ]
    .into_iter()
    .filter_map(|ct| {
        let rows: Vec<&Claim> = gold
            .iter()
            .filter(|c| c.check_type == ct && c.label.is_some())
            .collect();
        (!rows.is_empty()).then(|| row(ct, &rows, &said))
    })
    .collect()
}

// ── Weight tuning ─────────────────────────────────────────────────────────────

/**
 * Compute pack score boosts from successful outcome patterns.
 * Returns a map of pack → keyword → boost amount.
 *
 * Rules:
 * - Only boost from completed runs with 0 corrections
 * - Never boost above +2 per keyword
 * - Never create new keywords — only boost existing ones
 *
 * @param {RunOutcome[]} outcomes
 * @returns {Record<string, number>} packName → boost amount
 */
export function computePackBoosts(outcomes) {
  const boosts = {};

  const cleanRuns = outcomes.filter(
    o => o.selectedPack && o.completionStatus === "completed" && o.corrections === 0
  );

  for (const o of cleanRuns) {
    const pack = o.selectedPack;
    boosts[pack] = Math.min((boosts[pack] || 0) + 0.5, 2.0);
  }

  return boosts;
}

